//! The desktop binary: calls the `run()` entry point `frus::main!` generates in the
//! library. (On Android and the Web the entry point is `android_main` or `start`, both
//! generated by the same macro.)
//!
//! `cargo run -p frus-fetch-example`; add `RUST_LOG=info` for logs.

#[cfg(not(any(target_os = "android", target_arch = "wasm32")))]
fn main() -> frus::anyhow::Result<()> {
    frus_fetch_example::run()
}

#[cfg(any(target_os = "android", target_arch = "wasm32"))]
fn main() {}
